function EXPANSION_CONSTANT(G, S):
    best <- +infinity
    for k in 1 .. floor(|G|/2):
        if C(|G|, k) is small:
            candidates <- all k-subsets of G
        else:
            candidates <- a fixed number of random k-subsets of G
        for A in candidates:
            N <- { a*s mod : a in A, s in S }
            boundary <- N \ A
            best <- min(best, |boundary| / |A|)
    return best

